SELECT COUNT(*) FROM MARKUP_BOARD WHERE 1=1
AND B_STATUS = #{status}
AND B_TITLE LIKE '%' || #{keyword} || '%'

SELECT * FROM (
    SELECT it.*, ROWNUM rn FROM (
        SELECT * FROM MARKUP_BOARD
        WHERE 1=1

            AND B_STATUS = #{status}


            AND B_TITLE LIKE '%' || #{keyword} || '%'

        ORDER BY B_NO DESC
    ) it
    WHERE ROWNUM <= #{offset} + #{pageSize}
)
WHERE rn > #{offset}

