UPDATE MARKUP_BOARD 
SET 
    B_TITLE = #{b_title},
    B_STATUS = #{b_status, jdbcType=VARCHAR},
    B_CATEGORY = #{b_category, jdbcType=VARCHAR},
    B_COMMENT = #{b_comment, jdbcType=VARCHAR}

        , B_FILEPATH = #{b_filepath}

WHERE B_NO = #{b_no}
